ALTER TABLE `gram`.`agent_events` COMMENT COLUMN `skill_name` 'Skill family (skill_*). Skill invoked, when the record says so. Empty otherwise. Deprecated in favour of name. Still filled on api_request, where it describes the request rather than the subject, until a skill event type exists to carry name.';
ALTER TABLE `gram`.`agent_events` COMMENT COLUMN `agent_name` 'Agent family (agent_*). Sub-agent name, when the record says so. Empty otherwise. Deprecated in favour of name. Still filled on api_request, where it describes the request rather than the subject, until an agent event type exists to carry name.';
ALTER TABLE `gram`.`agent_events` COMMENT COLUMN `mcp_server_name` 'MCP family (mcp_*). MCP server involved, when the record says so. Empty otherwise.';
ALTER TABLE `gram`.`agent_events` COMMENT COLUMN `mcp_tool_name` 'MCP family (mcp_*). MCP tool involved, when the record says so. Empty otherwise. Deprecated in favour of name, which carries the tool on tool_call, tool_call_result and tool_decision whether or not it is an MCP tool.';
ALTER TABLE `gram`.`agent_events` COMMENT COLUMN `tool_name` 'Tool family (tool_*), for tools that are not MCP. Tool the record concerns, when the record says so. Empty otherwise. Deprecated in favour of name, which carries the tool on tool_call, tool_call_result and tool_decision whether or not it is an MCP tool.';
ALTER TABLE `gram`.`agent_events` COMMENT COLUMN `input_content` 'Deprecated, no replacement: text carries the words and attributes the structure. No longer filled. Was the normalized input message JSON.';
ALTER TABLE `gram`.`agent_events` COMMENT COLUMN `output_content` 'Deprecated, no replacement: text carries the words and attributes the structure. No longer filled. Was the normalized output message JSON.';
ALTER TABLE `gram`.`agent_events` ADD COLUMN `name` String COMMENT 'Name of the subject of the event, the generic pair to event_id: the tool on tool_call, tool_call_result and tool_decision (MCP or not), the skill on skill events and the agent on sub-agent events once those exist. Empty on prompt and api_* types, and when not stated. Replaces the per-family tool_name, mcp_tool_name, skill_name and agent_name columns.' CODEC(ZSTD(1)) AFTER `raw_event_name`;
